import React from 'react';
import { cn } from '@/lib/utils';

interface SkeletonProps extends React.HTMLAttributes<HTMLDivElement> {
  lines?: number;
  variant?: 'text' | 'card' | 'circular' | 'rectangular';
  className?: string;
}

export function Skeleton({
  lines = 3,
  variant = 'text',
  className,
  ...props
}: SkeletonProps) {
  const baseStyles = 'animate-pulse bg-gray-200 dark:bg-gray-700 rounded';

  const variantStyles = {
    text: 'h-4 w-full',
    card: 'h-32 w-full',
    circular: 'h-12 w-12 rounded-full',
    rectangular: 'h-20 w-full rounded-lg',
  };

  if (variant !== 'text') {
    return (
      <div
        className={cn(baseStyles, variantStyles[variant], className)}
        {...props}
      />
    );
  }

  return (
    <div className={cn('space-y-3', className)} {...props}>
      {Array.from({ length: lines }).map((_, index) => (
        <div
          key={index}
          className={cn(
            baseStyles,
            variantStyles.text,
            index === lines - 1 && 'w-3/4'
          )}
        />
      ))}
    </div>
  );
}

interface SkeletonCardProps extends React.HTMLAttributes<HTMLDivElement> {
  lines?: number;
  hasImage?: boolean;
  hasAction?: boolean;
  className?: string;
}

export function SkeletonCard({
  lines = 3,
  hasImage = true,
  hasAction = true,
  className,
  ...props
}: SkeletonCardProps) {
  return (
    <div className={cn('rounded-lg border border-gray-200 dark:border-gray-700 p-4 space-y-4', className)} {...props}>
      {hasImage && (
        <div className={cn(baseStyles, 'h-32 w-full rounded-lg')} />
      )}
      <div className="space-y-3">
        <div className={cn(baseStyles, 'h-6 w-3/4')} />
        {Array.from({ length: lines }).map((_, index) => (
          <div
            key={index}
            className={cn(
              baseStyles,
              'h-4 w-full',
              index === lines - 1 && 'w-5/6'
            )}
          />
        ))}
      </div>
      {hasAction && (
        <div className="flex items-center justify-end gap-2 pt-2">
          <div className={cn(baseStyles, 'h-8 w-20 rounded-md')} />
          <div className={cn(baseStyles, 'h-8 w-24 rounded-md bg-primary/20')} />
        </div>
      )}
    </div>
